COPY INTO PODCAST_DW.STAR.DIM_EPISODE FROM @PODCAST_DW.STAGE.LOAD_STAGE/star_dim_episode/ FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' NULL_IF=('') EMPTY_FIELD_AS_NULL=TRUE) ON_ERROR=ABORT_STATEMENT;

-- PUT 'file://<local path>/star/dim_show.csv' @PODCAST_DW.STAGE.LOAD_STAGE/star_dim_show/ AUTO_COMPRESS=TRUE OVERWRITE=TRUE;
COPY INTO PODCAST_DW.STAR.DIM_SHOW FROM @PODCAST_DW.STAGE.LOAD_STAGE/star_dim_show/ FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' NULL_IF=('') EMPTY_FIELD_AS_NULL=TRUE) ON_ERROR=ABORT_STATEMENT;

-- PUT 'file://<local path>/star/dim_creator.csv' @PODCAST_DW.STAGE.LOAD_STAGE/star_dim_creator/ AUTO_COMPRESS=TRUE OVERWRITE=TRUE;
COPY INTO PODCAST_DW.STAR.DIM_CREATOR FROM @PODCAST_DW.STAGE.LOAD_STAGE/star_dim_creator/ FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' NULL_IF=('') EMPTY_FIELD_AS_NULL=TRUE) ON_ERROR=ABORT_STATEMENT;

-- PUT 'file://<local path>/star/fact_listening_session.csv' @PODCAST_DW.STAGE.LOAD_STAGE/star_fact_listening_session/ AUTO_COMPRESS=TRUE OVERWRITE=TRUE;
COPY INTO PODCAST_DW.STAR.FACT_LISTENING_SESSION FROM @PODCAST_DW.STAGE.LOAD_STAGE/star_fact_listening_session/ FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' NULL_IF=('') EMPTY_FIELD_AS_NULL=TRUE) ON_ERROR=ABORT_STATEMENT;

-- PUT 'file://<local path>/star/fact_subscription.csv' @PODCAST_DW.STAGE.LOAD_STAGE/star_fact_subscription/ AUTO_COMPRESS=TRUE OVERWRITE=TRUE;
COPY INTO PODCAST_DW.STAR.FACT_SUBSCRIPTION FROM @PODCAST_DW.STAGE.LOAD_STAGE/star_fact_subscription/ FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' NULL_IF=('') EMPTY_FIELD_AS_NULL=TRUE) ON_ERROR=ABORT_STATEMENT;

-- Bronze: raw API responses, one JSON object per line (VARIANT columns) / Bronze:原始 API 响应,每行一个 JSON
COPY INTO PODCAST_DW.BRONZE.API_RAW FROM (SELECT $1:source_name::VARCHAR, $1:ingested_at::TIMESTAMP_TZ, $1:request_url::VARCHAR, $1:request_params, $1:http_status::NUMBER, $1:raw_payload FROM @PODCAST_DW.STAGE.LOAD_STAGE/bronze_api_raw/) FILE_FORMAT=(TYPE=JSON) ON_ERROR=ABORT_STATEMENT;

-- ======================================================================================
-- 3. Analytical queries Q1-Q5 (ROLLUP, GROUPING SETS, SCD2, window, retention) / 5 条分析查询
-- ======================================================================================

-- =====================================================================================
-- 02_analytical_queries.sql
-- Assignment 3, Part 2 - five analytical queries on the star schema (database PODCAST_DW).
-- 作业 3 第 2 部分 - 星型模型上的 5 条分析查询。
-- Each query starts with a marker line "-- @Qn | title"; pipeline/06_run_queries.py runs them one by one.
-- 每条查询以 "-- @Qn | 标题" 开头;pipeline/06_run_queries.py 逐条运行。
-- Plan tiers below are the plan the creator had ON THE EVENT DATE (SCD2 point-in-time), the history is simulated.
-- 下面的套餐是事件发生当天创作者所处的套餐(SCD2 时点),套餐历史是模拟的。
-- =====================================================================================

-- @Q1 | ROLLUP: listening hours by top-level category, then category, with subtotals and a grand total
-- 按一级类目、类目汇总收听小时,带小计和总计(ROLLUP)
SELECT IFF(GROUPING(s.top_category_name) = 1, '** ALL CATEGORIES **', s.top_category_name) AS top_category,
       IFF(GROUPING(s.category_name) = 1, '(subtotal)', s.category_name)                   AS category,
       COUNT(*)                                          AS sessions,
       ROUND(SUM(f.listened_seconds) / 3600, 1)          AS listening_hours,
       ROUND(100 * AVG(IFF(f.completed = 'Y', 1, 0)), 1) AS completion_rate_pct
FROM STAR.FACT_LISTENING_SESSION f
JOIN STAR.DIM_SHOW s ON f.show_sk = s.show_sk
GROUP BY ROLLUP (s.top_category_name, s.category_name)
ORDER BY GROUPING(s.top_category_name), s.top_category_name, GROUPING(s.category_name), listening_hours DESC;

-- @Q2 | GROUPING SETS: completion rate by creator plan (at the time) and device, with per-plan, per-device and overall rows
-- 按(当时)创作者套餐和设备统计完播率,同时给出按套餐、按设备和总体的行(GROUPING SETS)
SELECT COALESCE(c.plan_tier, 'ALL PLANS')      AS plan_tier_at_time,
       COALESCE(f.device_type, 'ALL DEVICES')  AS device_type,
       COUNT(*)                                          AS sessions,
       ROUND(AVG(f.listened_seconds) / 60, 1)            AS avg_minutes_listened,
       ROUND(100 * AVG(IFF(f.completed = 'Y', 1, 0)), 1) AS completion_rate_pct
FROM STAR.FACT_LISTENING_SESSION f
JOIN STAR.DIM_CREATOR c ON f.creator_sk = c.creator_sk
GROUP BY GROUPING SETS ((c.plan_tier, f.device_type), (c.plan_tier), (f.device_type), ())
ORDER BY GROUPING(c.plan_tier), c.plan_tier, GROUPING(f.device_type), f.device_type;

-- @Q3 | SCD2 in action: sessions by the plan at the time vs the creator's CURRENT plan (only creators whose plan changed)
-- SCD2 的作用:按"当时套餐"与"当前套餐"对比会话数(只看套餐变更过的创作者)
SELECT h.plan_tier   AS plan_at_time,
       cur.plan_tier AS plan_now,
       COUNT(DISTINCT h.creator_id)             AS creators,
       COUNT(*)                                 AS sessions,
       ROUND(SUM(f.listened_seconds) / 3600, 1) AS listening_hours
FROM STAR.FACT_LISTENING_SESSION f
JOIN STAR.DIM_CREATOR h   ON f.creator_sk = h.creator_sk
JOIN STAR.DIM_CREATOR cur ON cur.creator_id = h.creator_id AND cur.is_current
WHERE h.creator_id IN (SELECT creator_id FROM STAR.DIM_CREATOR GROUP BY creator_id HAVING COUNT(*) > 1)
GROUP BY h.plan_tier, cur.plan_tier
ORDER BY plan_at_time, plan_now;

-- @Q4 | Window function: top 3 shows per top-level category by listening hours
-- 窗口函数:每个一级类目收听小时最高的 3 档节目
WITH per_show AS (
  SELECT s.top_category_name, s.show_title, COUNT(*) AS sessions,
         ROUND(SUM(f.listened_seconds) / 3600, 1) AS listening_hours
  FROM STAR.FACT_LISTENING_SESSION f
  JOIN STAR.DIM_SHOW s ON f.show_sk = s.show_sk
  GROUP BY s.top_category_name, s.show_title),
ranked AS (
  SELECT *, RANK() OVER (PARTITION BY top_category_name ORDER BY listening_hours DESC) AS rank_in_category,
         ROUND(100 * listening_hours / SUM(listening_hours) OVER (PARTITION BY top_category_name), 1) AS share_of_category_pct
  FROM per_show)
SELECT top_category_name, rank_in_category, show_title, sessions, listening_hours, share_of_category_pct
FROM ranked
WHERE rank_in_category <= 3
ORDER BY top_category_name, rank_in_category;

-- @Q5 | 30-day retention per show: the 5 highest and 5 lowest shows (only shows with >= 30 observable subscriptions)
-- 按节目看 30 天留存:最高 5 档和最低 5 档(只看可观察订阅数 >= 30 的节目)
-- Small samples make rates noisy, so each show also gets a 95% Wilson confidence interval, and a flag says whether the
-- overall rate lies OUTSIDE that interval (i.e. the show differs from average more than chance alone would explain).
-- With ~80 shows tested, a few flags are expected by chance alone: read the list as "worth a look", not as proof.
-- 样本小时比例波动大,所以每档节目附带 95% Wilson 置信区间,并标注整体留存率是否落在区间之外(即差异超出随机波动)。
-- 同时检验约 80 档节目,即使没有真实差异也会有少数被标记:结果应理解为"值得关注",而不是定论。
WITH subs AS (
  SELECT fs.listener_sk, fs.show_sk, d.full_date AS sub_date
  FROM STAR.FACT_SUBSCRIPTION fs
  JOIN STAR.DIM_DATE d ON fs.date_key = d.date_key
  WHERE d.full_date <= DATE '2026-08-31'),
sess AS (
  SELECT f.listener_sk, f.show_sk, d.full_date AS session_date
  FROM STAR.FACT_LISTENING_SESSION f
  JOIN STAR.DIM_DATE d ON f.date_key = d.date_key),
flag AS (
  SELECT s.listener_sk, s.show_sk, MAX(IFF(x.session_date IS NOT NULL, 1, 0)) AS retained
  FROM subs s
  LEFT JOIN sess x
    ON x.listener_sk = s.listener_sk AND x.show_sk = s.show_sk
   AND x.session_date >= s.sub_date AND x.session_date < DATEADD('day', 30, s.sub_date)
  GROUP BY s.listener_sk, s.show_sk),
overall AS (SELECT SUM(retained) / COUNT(*) AS p_all FROM flag),
per_show AS (
  SELECT show_sk, COUNT(*) AS n, SUM(retained) AS retained_30d, SUM(retained) / COUNT(*) AS p
  FROM flag GROUP BY show_sk HAVING COUNT(*) >= 30),
scored AS (               -- Wilson interval, z = 1.96 / Wilson 区间
  SELECT p.*, 1.96 AS z,
         (p.p + 1.96 * 1.96 / (2 * p.n)) / (1 + 1.96 * 1.96 / p.n) AS centre,
         1.96 * SQRT(p.p * (1 - p.p) / p.n + 1.96 * 1.96 / (4 * p.n * p.n)) / (1 + 1.96 * 1.96 / p.n) AS half
  FROM per_show p),
ranked AS (
  SELECT sc.*, sh.show_title, sh.top_category_name,
         RANK() OVER (ORDER BY sc.p DESC) AS rk_high, RANK() OVER (ORDER BY sc.p ASC) AS rk_low
  FROM scored sc JOIN STAR.DIM_SHOW sh ON sc.show_sk = sh.show_sk)
SELECT IFF(rk_high <= 5, 'highest 5', 'lowest 5') AS grp, show_title, top_category_name,
       n AS subscriptions, retained_30d,
       ROUND(100 * p, 1) AS retention_30d_pct,
       ROUND(100 * (centre - half), 1) AS ci95_low_pct, ROUND(100 * (centre + half), 1) AS ci95_high_pct,
       ROUND(100 * o.p_all, 1) AS overall_pct,
       IFF(o.p_all < centre - half OR o.p_all > centre + half, 'yes', 'no') AS differs_from_overall
FROM ranked CROSS JOIN overall o
WHERE rk_high <= 5 OR rk_low <= 5
ORDER BY p DESC;

-- ======================================================================================
-- 4. Optimization of Q5 / Q5 优化
-- ======================================================================================

-- 4a. Version A (rewrite) and version B (reads the pre-computed table) / 版本 A(改写)与 B(读预计算表)
-- =====================================================================================
-- 03_q5_optimizations.sql
-- Assignment 3, Part 2 - optimized versions of Q5 (the most expensive query, see logs/query_metrics.csv).
-- 作业 3 第 2 部分 - Q5(最耗资源的查询)的优化版本。
-- A = rewrite, B = pre-computed table. C (clustering) re-runs the ORIGINAL Q5 after sql/03c_cluster_on.sql.
-- A = 改写,B = 预计算表。C(聚簇)是在运行 03c_cluster_on.sql 之后重跑原始 Q5。
-- Run: python pipeline/06_run_queries.py Q5A --file sql/03_q5_optimizations.sql --repeat 5 --label A_rewrite
-- =====================================================================================

-- @Q5A | Optimization A (query rewrite): semi-join with EXISTS instead of LEFT JOIN + MAX over every matching session
-- 优化 A(改写查询):用 EXISTS 半连接代替"左连接所有匹配会话再 MAX",不再把一条订阅展开成多行
-- Same question and same output columns as Q5 in 02_analytical_queries.sql; only the way `flag` is computed differs.
-- 问题和输出列与 02 文件里的 Q5 完全相同,只有 `flag`(每条订阅是否留存)的计算方式不同。
WITH subs AS (
  SELECT fs.listener_sk, fs.show_sk, d.full_date AS sub_date
  FROM STAR.FACT_SUBSCRIPTION fs
  JOIN STAR.DIM_DATE d ON fs.date_key = d.date_key
  WHERE d.full_date <= DATE '2026-08-31'),
sess AS (
  SELECT DISTINCT f.listener_sk, f.show_sk, d.full_date AS session_date      -- one row per (listener, show, day) / 同一天多次会话只留一行
  FROM STAR.FACT_LISTENING_SESSION f
  JOIN STAR.DIM_DATE d ON f.date_key = d.date_key),
matched AS (
  SELECT s.listener_sk, s.show_sk
  FROM subs s
  WHERE EXISTS (SELECT 1 FROM sess x
                WHERE x.listener_sk = s.listener_sk AND x.show_sk = s.show_sk
                  AND x.session_date >= s.sub_date AND x.session_date < DATEADD('day', 30, s.sub_date))),
flag AS (
  SELECT s.listener_sk, s.show_sk, IFF(m.listener_sk IS NULL, 0, 1) AS retained
  FROM subs s LEFT JOIN matched m ON m.listener_sk = s.listener_sk AND m.show_sk = s.show_sk),
overall AS (SELECT SUM(retained) / COUNT(*) AS p_all FROM flag),
per_show AS (
  SELECT show_sk, COUNT(*) AS n, SUM(retained) AS retained_30d, SUM(retained) / COUNT(*) AS p
  FROM flag GROUP BY show_sk HAVING COUNT(*) >= 30),
scored AS (               -- Wilson interval, z = 1.96 / Wilson 区间
  SELECT p.*, 1.96 AS z,
         (p.p + 1.96 * 1.96 / (2 * p.n)) / (1 + 1.96 * 1.96 / p.n) AS centre,
         1.96 * SQRT(p.p * (1 - p.p) / p.n + 1.96 * 1.96 / (4 * p.n * p.n)) / (1 + 1.96 * 1.96 / p.n) AS half
  FROM per_show p),
ranked AS (
  SELECT sc.*, sh.show_title, sh.top_category_name,
         RANK() OVER (ORDER BY sc.p DESC) AS rk_high, RANK() OVER (ORDER BY sc.p ASC) AS rk_low
  FROM scored sc JOIN STAR.DIM_SHOW sh ON sc.show_sk = sh.show_sk)
SELECT IFF(rk_high <= 5, 'highest 5', 'lowest 5') AS grp, show_title, top_category_name,
       n AS subscriptions, retained_30d,
       ROUND(100 * p, 1) AS retention_30d_pct,
       ROUND(100 * (centre - half), 1) AS ci95_low_pct, ROUND(100 * (centre + half), 1) AS ci95_high_pct,
       ROUND(100 * o.p_all, 1) AS overall_pct,
       IFF(o.p_all < centre - half OR o.p_all > centre + half, 'yes', 'no') AS differs_from_overall
FROM ranked CROSS JOIN overall o
WHERE rk_high <= 5 OR rk_low <= 5
ORDER BY p DESC;

-- @Q5B | Optimization B (pre-computed): read the retention flag from STAR.AGG_SUBSCRIPTION_RETENTION
-- 优化 B(预计算):直接读 STAR.AGG_SUBSCRIPTION_RETENTION 里提前算好的留存标记
-- The table is built once by sql/03a_setup_agg_table.sql (that one-off cost is reported separately).
-- 该表由 sql/03a_setup_agg_table.sql 一次性建好(这笔一次性成本单独报告)。
-- Same question and same output columns as Q5 in 02_analytical_queries.sql; only the way `flag` is computed differs.
-- 问题和输出列与 02 文件里的 Q5 完全相同,只有 `flag`(每条订阅是否留存)的计算方式不同。
WITH flag AS (
  SELECT listener_sk, show_sk, retained_30d AS retained
  FROM STAR.AGG_SUBSCRIPTION_RETENTION
  WHERE is_observable = 1),
overall AS (SELECT SUM(retained) / COUNT(*) AS p_all FROM flag),
per_show AS (
  SELECT show_sk, COUNT(*) AS n, SUM(retained) AS retained_30d, SUM(retained) / COUNT(*) AS p
  FROM flag GROUP BY show_sk HAVING COUNT(*) >= 30),
scored AS (               -- Wilson interval, z = 1.96 / Wilson 区间
  SELECT p.*, 1.96 AS z,
         (p.p + 1.96 * 1.96 / (2 * p.n)) / (1 + 1.96 * 1.96 / p.n) AS centre,
         1.96 * SQRT(p.p * (1 - p.p) / p.n + 1.96 * 1.96 / (4 * p.n * p.n)) / (1 + 1.96 * 1.96 / p.n) AS half
  FROM per_show p),
ranked AS (
  SELECT sc.*, sh.show_title, sh.top_category_name,
         RANK() OVER (ORDER BY sc.p DESC) AS rk_high, RANK() OVER (ORDER BY sc.p ASC) AS rk_low
  FROM scored sc JOIN STAR.DIM_SHOW sh ON sc.show_sk = sh.show_sk)
SELECT IFF(rk_high <= 5, 'highest 5', 'lowest 5') AS grp, show_title, top_category_name,
       n AS subscriptions, retained_30d,
       ROUND(100 * p, 1) AS retention_30d_pct,
       ROUND(100 * (centre - half), 1) AS ci95_low_pct, ROUND(100 * (centre + half), 1) AS ci95_high_pct,
       ROUND(100 * o.p_all, 1) AS overall_pct,
       IFF(o.p_all < centre - half OR o.p_all > centre + half, 'yes', 'no') AS differs_from_overall
FROM ranked CROSS JOIN overall o
WHERE rk_high <= 5 OR rk_low <= 5
ORDER BY p DESC;

-- 4b. Build the pre-computed table for B (run once, 1.3 s) / 构建 B 用的预计算表(只需运行一次)
-- Optimization B setup: pre-compute, once, whether each subscription was retained within 30 days.
-- 优化 B 的准备:一次性算好"每条订阅是否在 30 天内留存"。
-- Trade-off: the work moves from query time to load time, and the table must be rebuilt when new sessions or subscriptions arrive.
-- 代价:计算从查询时移到加载时;有新会话或新订阅时要重建。
CREATE OR REPLACE TABLE STAR.AGG_SUBSCRIPTION_RETENTION AS
WITH subs AS (
  SELECT fs.listener_sk, fs.show_sk, d.full_date AS sub_date
  FROM STAR.FACT_SUBSCRIPTION fs JOIN STAR.DIM_DATE d ON fs.date_key = d.date_key),
sess AS (
  SELECT f.listener_sk, f.show_sk, d.full_date AS session_date
  FROM STAR.FACT_LISTENING_SESSION f JOIN STAR.DIM_DATE d ON f.date_key = d.date_key)
SELECT s.listener_sk, s.show_sk, s.sub_date,
       MAX(IFF(x.session_date IS NOT NULL, 1, 0)) AS retained_30d,
       IFF(s.sub_date <= DATE '2026-08-31', 1, 0) AS is_observable      -- full 30-day window exists / 30 天窗口完整
FROM subs s
LEFT JOIN sess x
  ON x.listener_sk = s.listener_sk AND x.show_sk = s.show_sk
 AND x.session_date >= s.sub_date AND x.session_date < DATEADD('day', 30, s.sub_date)
GROUP BY s.listener_sk, s.show_sk, s.sub_date;

-- 4c. Clustering test: on, then off again (no effect was measured) / 聚类测试:开启后又关闭(未测得效果)
-- Optimization C setup: define a clustering key on both fact tables (then re-run the ORIGINAL Q5).
-- 优化 C 的准备:给两张事实表定义聚簇键(然后重跑原始 Q5)。
-- Note: Snowflake re-clusters in the background with serverless compute, which uses a small amount of credits.
-- 注意:Snowflake 会在后台用无服务器计算重新聚簇,会消耗少量额度。
ALTER TABLE STAR.FACT_LISTENING_SESSION CLUSTER BY (show_sk, date_key);
ALTER TABLE STAR.FACT_SUBSCRIPTION CLUSTER BY (show_sk, date_key);

-- Undo optimization C: remove the clustering keys so later runs start from the baseline layout.
-- 撤销优化 C:删除聚簇键,让之后的测试回到基线状态。
ALTER TABLE STAR.FACT_LISTENING_SESSION DROP CLUSTERING KEY;
ALTER TABLE STAR.FACT_SUBSCRIPTION DROP CLUSTERING KEY;

-- ======================================================================================
-- 5. Part 4a: three warehouse queries (time series, CUBE, SCD2 + running total) / 第 4a 部分的 3 条查询
-- ======================================================================================

-- =====================================================================================
-- 04_part4a_queries.sql
-- Assignment 3, Part 4a - three relational queries on the star schema (database PODCAST_DW).
-- 作业 3 第 4a 部分 - 星型模型上的 3 条关系型查询。
-- Markers "-- @Rn | title" are read by pipeline/06_run_queries.py:  python pipeline/06_run_queries.py R1 --file sql/04_part4a_queries.sql
-- 标记行 "-- @Rn | 标题" 由 06_run_queries.py 读取。
-- These three use what the relational model is best at: time series, multi-dimension cubes, SCD2 point-in-time + running totals.
-- 这 3 条展示关系型擅长的事:时间序列、多维立方体、SCD2 时点加累计。
-- =====================================================================================

-- @R1 | Monthly listening trend with month-over-month change and a 3-month moving average
-- 每月收听趋势:环比变化和 3 个月移动平均
SELECT d.year, d.month,
       COUNT(*)                                   AS sessions,
       ROUND(SUM(f.listened_seconds) / 3600, 1)   AS listening_hours,
       ROUND(100 * (SUM(f.listened_seconds) / NULLIF(LAG(SUM(f.listened_seconds)) OVER (ORDER BY d.year, d.month), 0) - 1), 1)
                                                  AS hours_mom_pct,
       ROUND(AVG(SUM(f.listened_seconds) / 3600) OVER (ORDER BY d.year, d.month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1)
                                                  AS hours_3m_moving_avg
FROM STAR.FACT_LISTENING_SESSION f
JOIN STAR.DIM_DATE d ON f.date_key = d.date_key
GROUP BY d.year, d.month
ORDER BY d.year, d.month;

-- @R2 | CUBE: listening hours and completion rate for every combination of top-level category and device (incl. subtotals)
-- CUBE:一级类目与设备的所有组合的收听小时和完播率(含各级小计)
SELECT COALESCE(s.top_category_name, 'ALL CATEGORIES') AS top_category,
       COALESCE(f.device_type, 'ALL DEVICES')          AS device_type,
       COUNT(*)                                          AS sessions,
       ROUND(SUM(f.listened_seconds) / 3600, 1)          AS listening_hours,
       ROUND(100 * AVG(IFF(f.completed = 'Y', 1, 0)), 1) AS completion_rate_pct
FROM STAR.FACT_LISTENING_SESSION f
JOIN STAR.DIM_SHOW s ON f.show_sk = s.show_sk
GROUP BY CUBE (s.top_category_name, f.device_type)
ORDER BY GROUPING(s.top_category_name), s.top_category_name, GROUPING(f.device_type), listening_hours DESC;

-- @R3 | New subscriptions per quarter by the creator's plan AT SUBSCRIPTION TIME (SCD2), with a running total per plan
-- 每季度新增订阅数,按订阅当时创作者的套餐(SCD2)分组,并给出每个套餐的累计值
SELECT d.year, d.quarter, c.plan_tier AS plan_at_subscription,
       SUM(fs.subscription_count) AS new_subscriptions,
       SUM(SUM(fs.subscription_count)) OVER (PARTITION BY c.plan_tier ORDER BY d.year, d.quarter) AS running_total
FROM STAR.FACT_SUBSCRIPTION fs
JOIN STAR.DIM_DATE d    ON fs.date_key = d.date_key
JOIN STAR.DIM_CREATOR c ON fs.creator_sk = c.creator_sk
GROUP BY d.year, d.quarter, c.plan_tier
ORDER BY c.plan_tier, d.year, d.quarter;

-- ======================================================================================
-- 6. SCD2 proof: expired and active versions of two creators / SCD2 证明:两位创作者的过期版本与当前版本
-- ======================================================================================

SELECT creator_sk, creator_id, plan_tier, valid_from, valid_to, is_current
FROM STAR.DIM_CREATOR
WHERE creator_id IN (5, 26)
ORDER BY creator_id, valid_from;
